16		"github.com/spf13/cobra"
17	)
18	
19	// Regression Radar: turn the brain from a passive librarian into an active reviewer.
20	// Given a query (task description + failing identifiers) it compares the CURRENT working
21	// tree against what the session history asserts the code looked like, and flags two narrow,
22	// high-precision shapes of regression:
23	//
24	//	changed: history asserts `<id> + "<literal>"` (or a `..` range) at a locus, but the
25	//	         current tree keeps the distinctive operand while the identifier was swapped out
26	//	         (e.g. scopeBaseRef+"..HEAD"  ->  "master..HEAD").
27	//	deleted: history asserts an assignment whose target contains <id> (e.g.
28	//	         `state.TranscriptPath = resolved`) and that assignment is now absent EVERYWHERE in
29	//	         the candidate locus/file, though the identifier still lives in the tree.
30	//
31	// It reads RAW sessions (inspectBrainRawText), not the index, because the indexed Summary
32	// collapses code to prose; the precise invariant survives only in raw text. History file hints
33	// keep multi-locus checks local, so an intact peer file/site cannot mask a nearby regressed site.
34	// Unhinted fallbacks stay conservative and global to avoid noisy deletion claims.
35	
36	const (
37		regressionMaxFileBytes = 1 << 20
38		regressionMaxAnomalies = 50
39	)
40	
41	type regressionAnomaly struct {
42		File             string   `json:"file"`
43		Line             int      `json:"line,omitempty"`
44		Kind             string   `json:"kind"` // "changed" | "deleted"
45		Current          string   `json:"current"`
46		Expected         string   `json:"expected"`
47		Identifier       string   `json:"identifier"`
48		Symbol           string   `json:"symbol,omitempty"`
49		RelatedLocations []string `json:"related_locations,omitempty"`
50		Confidence       float64  `json:"confidence"`
51		Reason           string   `json:"reason"`
52		Evidence         string   `json:"evidence"`
53		rankBoost        int
54	}
55	
56	type regressionReport struct {
57		SchemaVersion int                 `json:"schema_version"` // shares reviewReportSchemaVersion; see docs/diffless_review_seam.md
58		GeneratedAt   time.Time           `json:"generated_at"`
59		Query         string              `json:"query"`
60		RepoPath      string              `json:"repo_path"`
61		BrainPath     string              `json:"brain_path"`
62		Anomalies     []regressionAnomaly `json:"anomalies"`
63		Scanned       int                 `json:"scanned_files"`
64		Warnings      []string            `json:"warnings,omitempty"`
65	}
66	
67	type regressionDetectorOptions struct {
68		limit            int
69		json             bool
70		includeDeletions bool // deletions are higher-recall but noisier (no recency data); opt-in
71		locationOnly     bool // emit file:line only, NOT expected/current — so a fair A/B can't paste the answer
72	}
73	
74	type changeSignal struct {
75		id      string   // lowercased identifier
76		operand string   // distinctive operand, lowercased+despaced (e.g. `..head`)
77		raw     string   // human-readable asserted expression
78		ev      string   // session path:line
79		hints   []string // code files named on the same history line as the asserted invariant
80	}
81	
82	type deleteSignal struct {
83		id      string
84		target  string // normalized LHS/callee + operator (e.g. `state.transcriptpath=` or `state.realign(`)
85		rhs     string // despaced right-hand side / first argument token — used to locate the home file
86		raw     string
87		ev      string
88		hints   []string // code files named on the same history line as the asserted invariant
89		anchors []string // peer assignments from the same history line, used to localize missing calls
90	}
91	
92	type candFile struct {
93		clean    string
94		lines    []string
95		norm     []string
96		semantic bool // surfaced by the semantic index (a primary locus), not just named in a session
97		rank     int  // semantic rank (lower = stronger locus)
98		isTest   bool
99	}
100	
101	func regressionIsComment(line string) bool {
102		t := strings.TrimSpace(line)
103		return strings.HasPrefix(t, "//") || strings.HasPrefix(t, "*") || strings.HasPrefix(t, "/*") ||
104			strings.HasPrefix(t, "#") || strings.HasPrefix(t, "<!--")
105	}
106	
107	func regressionIsTestPath(p string) bool {
108		l := strings.ToLower(p)
109		return strings.Contains(l, "_test.") || strings.Contains(l, ".test.") || strings.Contains(l, ".spec.") ||
110			strings.Contains(l, "/test/") || strings.Contains(l, "/tests/") || strings.Contains(l, "/testdata/")
111	}
112	
113	var regressionCodeFilePattern = regexp.MustCompile(`[\w./-]+\.(?:go|ts|tsx|js|jsx|py|rs|java|kt|swift|c|cc|cpp|h|hpp)`)
114	
115	func regressionDespace(s string) string {
116		var b strings.Builder
117		for _, r := range s {
118			if r == ' ' || r == '\t' {
119				continue
120			}
121			b.WriteRune(r)
122		}
123		return strings.ToLower(b.String())
124	}
125	
126	func regressionLineFileHints(line string) []string {
127		seen := map[string]struct{}{}
128		var out []string
129		for _, fn := range regressionCodeFilePattern.FindAllString(line, -1) {
130			clean := filepath.Clean(strings.TrimLeft(fn, "+-/ "))
131			if clean == "." || filepath.IsAbs(clean) || strings.HasPrefix(clean, "..") {
132				continue
133			}
134			clean = filepath.ToSlash(clean)
135			if _, ok := seen[clean]; ok {
136				continue
137			}
138			seen[clean] = struct{}{}
139			out = append(out, clean)
140		}
141		return out
142	}
143	
144	func mergeRegressionHints(a, b []string) []string {
145		if len(b) == 0 {
146			return a
147		}
148		seen := map[string]struct{}{}
149		out := make([]string, 0, len(a)+len(b))
150		for _, h := range a {
151			if h == "" {
152				continue
153			}
154			seen[h] = struct{}{}
155			out = append(out, h)
156		}
157		for _, h := range b {
158			if h == "" {
159				continue
160			}
161			if _, ok := seen[h]; ok {
162				continue
163			}
164			seen[h] = struct{}{}
165			out = append(out, h)
166		}
167		return out
168	}
169	
170	// regressionExtractSignals pulls change + delete signals for one identifier from a (space-
171	// collapsed) history excerpt using identifier-anchored regexes — tight enough that line-number
172	// noise and common tokens don't leak in.
173	func regressionExtractSignals(id, excerpt, ev string) ([]changeSignal, []deleteSignal) {
174		q := regexp.QuoteMeta(id)
175		// Known recall limits (documented, not silently dropped): literals >80 chars are skipped, an
176		// all-lowercase identifier is never extracted as a query id upstream, and a literal that embeds
177		// the id (e.g. `foo+"foobar"`) won't match. These bound recall, not precision.
178		changeRe := regexp.MustCompile(`(?i)` + q + `\s*\+?\s*(?:"([^"]{2,80})"|([A-Za-z0-9_]*\.\.[A-Za-z0-9_]+))`)
179		assignRe := regexp.MustCompile(`(?i)((?:[A-Za-z0-9_]+\.)*[A-Za-z0-9_]+)\s*(:?=)\s*([A-Za-z0-9_."'\[\]()+\-* ]{1,48})`)
180		callRe := regexp.MustCompile(`(?i)((?:[A-Za-z0-9_]+\.)*[A-Za-z0-9_]*` + q + `[A-Za-z0-9_]*)\s*\(\s*([A-Za-z0-9_."'\[\]+\-* ]{1,48})\s*\)`)
181	
182		var changes []changeSignal
183		seenC := map[string]struct{}{}
184		for _, m := range changeRe.FindAllStringSubmatch(excerpt, -1) {
185			operand := m[1]
186			if operand == "" {
187				operand = m[2]
188			}
189			operand = regressionDespace(operand)
190			if len(operand) < 4 {
191				continue
192			}
193			if _, ok := seenC[operand]; ok {
194				continue
195			}
196			seenC[operand] = struct{}{}
197			changes = append(changes, changeSignal{id: id, operand: operand, raw: strings.TrimSpace(m[0]), ev: ev})
198		}
199	
200		var deletes []deleteSignal
201		seenD := map[string]struct{}{}
202		var peerAssignments []deleteSignal
203		for _, m := range assignRe.FindAllStringSubmatch(excerpt, -1) {
204			lhs := regressionDespace(m[1])
205			op := m[2]
206			// Only field/state assignments (`a.b = c`) are persistent invariants whose absence is a
207			// regression; `:=` locals are ephemeral, so their absence from a file is meaningless.
208			if op != "=" || !strings.Contains(lhs, ".") {
209				continue
210			}
211			target := lhs + op
212			rhsTok := regressionSignalHead(m[3])
213			if rhsTok == "" {
214				continue
215			}
216			peerAssignments = append(peerAssignments, deleteSignal{target: target, rhs: rhsTok})
217			if !strings.Contains(lhs, id) {
218				continue
219			}
220			k := target + "|" + rhsTok
221			if _, ok := seenD[k]; ok {
222				continue
223			}
224			seenD[k] = struct{}{}
225			raw := strings.TrimSpace(m[1]) + " " + op + " " + rhsTok
226			deletes = append(deletes, deleteSignal{id: id, target: target, rhs: rhsTok, raw: raw, ev: ev})
227		}
228		for _, m := range callRe.FindAllStringSubmatch(excerpt, -1) {
229			callee := regressionDespace(m[1])
230			if !strings.Contains(callee, id) || !strings.Contains(callee, ".") {
231				continue
232			}
233			argTok := regressionSignalHead(m[2])
234			if argTok == "" {
235				continue
236			}
237			target := callee + "("
238			k := target + "|" + argTok
239			if _, ok := seenD[k]; ok {
240				continue
241			}
242			seenD[k] = struct{}{}
243			var anchors []string
244			for _, p := range peerAssignments {
245				if p.rhs == argTok && p.target != target {
246					anchors = append(anchors, p.target)
247				}
248			}
249			raw := strings.TrimSpace(m[1]) + "(" + argTok + ")"
250			deletes = append(deletes, deleteSignal{id: id, target: target, rhs: argTok, raw: raw, ev: ev, anchors: anchors})
251		}
252		return changes, deletes
253	}
254	
255	func regressionSignalHead(raw string) string {
256		token := strings.TrimSpace(raw)
257		token = strings.TrimLeft(token, "\"'`([{")
258		token = strings.TrimRight(token, "\"'`)]},;")
259		for i := 0; i < len(token); i++ {
260			c := token[i]
261			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' {
262				continue
263			}
264			token = token[:i]
265			break
266		}
267		return strings.ToLower(token)
268	}
269	
270	// regressionScanHistory walks the raw brain (sessions + exports) once and extracts change/delete
271	// signals for the given identifiers from EVERY matching line — not a capped top-N — so rare but
272	// precise invariants are not lost. Bounded by a generous file cap and a distinct-signal cap.
273	func regressionScanHistory(brainDir string, ids []string) ([]changeSignal, []deleteSignal, map[string]struct{}) {
274		const (
275			maxFiles       = 20000
276			maxLineBytes   = 4 * 1024 * 1024
277			maxSignalsEach = 400
278		)
279		lowIDs := make([]string, 0, len(ids))
280		for _, id := range ids {
281			lowIDs = append(lowIDs, strings.ToLower(id))
282		}
283		var changes []changeSignal
284		var deletes []deleteSignal
285		files := map[string]struct{}{}
286		seenC := map[string]int{}
287		seenD := map[string]int{}
288		scanned := 0
289		_ = filepath.WalkDir(brainDir, func(path string, d fs.DirEntry, err error) error {
290			if err != nil {
291				return nil
292			}
293			if d.IsDir() {
294				if n := d.Name(); n == semanticDirName || n == ".git" {
295					return filepath.SkipDir
296				}
297				return nil
298			}
299			if scanned >= maxFiles || (len(seenC) >= maxSignalsEach && len(seenD) >= maxSignalsEach) {
300				return filepath.SkipAll
301			}
302			switch filepath.Ext(path) {
303			case ".jsonl", ".json", ".md", ".txt":
304			default:
305				return nil
306			}
307			rel, _ := filepath.Rel(brainDir, path)
308			relSlash := filepath.ToSlash(rel)
309			if relSlash == "manifest.json" || strings.HasPrefix(relSlash, "seed/") {
310				return nil
311			}
312			f, openErr := os.Open(path)
313			if openErr != nil {
314				return nil
315			}
316			defer f.Close()
317			scanned++
318			sc := bufio.NewScanner(f)
319			sc.Buffer(make([]byte, 0, 64*1024), maxLineBytes)
320			lineNo := 0
321			for sc.Scan() {
322				lineNo++
323				line := sc.Text()
324				low := strings.ToLower(line)
325				matched := false
326				for _, id := range lowIDs {
327					if !strings.Contains(low, id) {
328						continue
329					}
330					matched = true
331					ex := normalizeHistoryTextForExcerpt(line)
332					ev := relSlash + ":" + strconv.Itoa(lineNo)
333					c, dl := regressionExtractSignals(id, ex, ev)
334					hints := regressionLineFileHints(line)
335					for _, s := range c {
336						s.hints = hints
337						k := s.id + "|" + s.operand
338						if idx, ok := seenC[k]; ok {
339							changes[idx].hints = mergeRegressionHints(changes[idx].hints, hints)
340						} else {
341							seenC[k] = len(changes)
342							changes = append(changes, s)
343						}
344					}
345					for _, s := range dl {
346						s.hints = hints
347						k := s.target + "|" + s.rhs
348						if idx, ok := seenD[k]; ok {
349							deletes[idx].hints = mergeRegressionHints(deletes[idx].hints, hints)
350							deletes[idx].anchors = mergeRegressionHints(deletes[idx].anchors, s.anchors)
351						} else {
352							seenD[k] = len(deletes)
353							deletes = append(deletes, s)
354						}
355					}
356				}
357				if matched {
358					for _, fn := range regressionLineFileHints(line) {
359						files[fn] = struct{}{}
360					}
361				}
362			}
363			return nil
364		})
365		return changes, deletes, files
366	}
367	
368	func detectRegressionAnomalies(brainDir, repoRoot string, semSource *semanticSourceManifest, query string, limit int, includeDeletions bool) ([]regressionAnomaly, int, []string) {
369		var warnings []string
370		ids := brainBriefRawHistoryQueries(query)
371		if len(ids) == 0 {
372			return []regressionAnomaly{}, 0, []string{"no code identifiers found in query; pass the failing symbols/terms"}
373		}
374	
375		candidateFiles := map[string]struct{}{}
376		semanticRank := map[string]int{} // clean path -> best (lowest) semantic rank; lower = stronger locus
377		for _, rawID := range ids {
378			id := strings.ToLower(rawID)
379			if semSource != nil {
380				if syms, _, _, err := semanticContextFacts(brainDir, semSource, id, 8, 0); err == nil {
381					for rank, s := range syms {
382						if s.FilePath == "" {
383							continue
384						}
385						candidateFiles[s.FilePath] = struct{}{}
386						c := filepath.Clean(s.FilePath)
387						if r, ok := semanticRank[c]; !ok || rank < r {
388							semanticRank[c] = rank
389						}
390					}
391				}
392			}
393		}
394		// Targeted history scan: walk the raw sessions once, keeping only signal-bearing lines (so a
395		// rare invariant isn't lost behind thousands of plain identifier mentions, as a capped
396		// generic scan would). Also collects the code files those sessions name.
397		changes, deletes, namedFiles := regressionScanHistory(brainDir, ids)
398		for f := range namedFiles {
399			candidateFiles[f] = struct{}{}
400		}
401		if len(changes) == 0 && len(deletes) == 0 {
402			return []regressionAnomaly{}, 0, append(warnings, "history holds no precise code assertions for these identifiers")
403		}
404	
405		// Load all candidate files once.
406		var files []candFile
407		for file := range candidateFiles {
408			clean := filepath.Clean(file)
409			if strings.HasPrefix(clean, "..") || filepath.IsAbs(clean) {
410				continue
411			}
412			full := filepath.Join(repoRoot, clean)
413			if err := rejectSymlinkPathComponents(repoRoot, clean); err != nil {
414				continue // per-component symlink guard, matching the brain's other repo reads
415			}
416			info, err := os.Stat(full)
417			if err != nil || info.IsDir() || info.Size() > regressionMaxFileBytes {
418				continue
419			}
420			data, err := os.ReadFile(full)
421			if err != nil {
422				continue
423			}
424			lines := strings.Split(string(data), "\n")
425			norm := make([]string, len(lines))
426			for i, ln := range lines {
427				norm[i] = regressionDespace(ln)
428			}
429			rank, isSem := semanticRank[clean]
430			if !isSem {
431				rank = 1 << 30
432			}
433			files = append(files, candFile{clean: clean, lines: lines, norm: norm, semantic: isSem, rank: rank, isTest: regressionIsTestPath(clean)})
434		}
435		if len(files) == 0 {
436			return []regressionAnomaly{}, 0, append(warnings, "no current files to verify against (semantic index missing?)")
437		}
438		// Deterministic, locus-prioritized order: implementation before tests, then by semantic rank
439		// (the strongest fix-site first), then path — so a finding lands on the actual fix site, not a
440		// random file that happens to share a common operand like `..HEAD`.
441		sort.SliceStable(files, func(i, j int) bool {
442			if files[i].isTest != files[j].isTest {
443				return !files[i].isTest
444			}
445			if files[i].rank != files[j].rank {
446				return files[i].rank < files[j].rank
447			}
448			return files[i].clean < files[j].clean
449		})
450	
451		// "invariant still holds" check — must use the SAME comment/test filter as the emit loop, or a
452		// stale comment/test copy of `operand+id` would falsely suppress a real regression (false negative).
453		fileLineBoth := func(f candFile, a, b string) bool {
454			if f.isTest {
455				return false
456			}
457			for i, n := range f.norm {
458				if regressionIsComment(f.lines[i]) {
459					continue
460				}
461				if strings.Contains(n, a) && strings.Contains(n, b) {
462					return true
463				}
464			}
465			return false
466		}
467		anyLineBoth := func(a, b string) bool {
468			for _, f := range files {
469				if fileLineBoth(f, a, b) {
470					return true
471				}
472			}
473			return false
474		}
475		anyHas := func(needle string) bool {
476			for _, f := range files {
477				for _, n := range f.norm {
478					if strings.Contains(n, needle) {
479						return true
480					}
481				}
482			}
483			return false
484		}
485	
486		var anomalies []regressionAnomaly
487	
488		for _, c := range dedupeChanges(changes) {
489			// Likely-rename guard: if the operand is still concatenated to SOME identifier
490			// (`<ident> + "...operand..."`, structure preserved), the invariant is intact under a renamed
491			// symbol, not regressed — only flag when the operand now sits in a bare/hardcoded literal.
492			renameRe := regexp.MustCompile(`[a-z_][a-z0-9_]*\s*\+\s*"[^"]*` + regexp.QuoteMeta(c.operand))
493			hinted := map[string]struct{}{}
494			for _, h := range c.hints {
495				hinted[filepath.Clean(h)] = struct{}{}
496			}
497			if len(hinted) == 0 && anyLineBoth(c.operand, c.id) {
498				continue // invariant still holds somewhere, and history did not name per-file loci
499			}
500			found := false
501			for _, f := range files { // locate the swap: operand present, identifier gone
502				if len(hinted) > 0 {
503					if _, ok := hinted[f.clean]; !ok {
504						continue
505					}
506					if fileLineBoth(f, c.operand, c.id) {
507						continue // this hinted file still holds the invariant; do not let it mask peers
508					}
509				}
510				if f.isTest {
511					continue // a test's `..HEAD` is not the regressed implementation site
512				}
513				for i, n := range f.norm {
514					if regressionIsComment(f.lines[i]) {
515						continue // prose mentions of a range like `main...HEAD` are not the regression
516					}
517					if strings.Contains(n, c.operand) && !strings.Contains(n, c.id) {
518						if renameRe.MatchString(strings.ToLower(f.lines[i])) {
519							continue // operand still concatenated to an identifier → benign rename, not a regression
520						}
521						anomalies = append(anomalies, regressionAnomaly{
522							File: f.clean, Line: i + 1, Kind: "changed",
523							Current: strings.TrimSpace(f.lines[i]), Expected: c.raw,
524							Identifier: c.id, Confidence: 0.8, Evidence: c.ev,
525							Reason: fmt.Sprintf("suspected regression: history asserts %q; this line keeps %q but dropped %q (could also be a rename — verify)", c.raw, c.operand, c.id),
526						})
527						found = true
528						break
529					}
530				}
531				if found && len(hinted) == 0 {
532					break
533				}
534			}
535		}
536	
537		for _, d := range dedupeDeletes(deletes) {
538			if !includeDeletions {
539				break // deletions are higher-recall but noisier (benign churn) — opt-in only
540			}
541			// The SPECIFIC assignment (target + its RHS) must be absent everywhere — a different
542			// assignment to the same field in another file is not this regression.
543			isCallDeletion := strings.HasSuffix(d.target, "(")
544			if isCallDeletion && len(d.anchors) > 0 {
545				homes := regressionMissingCallHomes(files, d)
546				if len(homes) > 0 {
547					for _, h := range homes {
548						anomalies = append(anomalies, regressionAnomaly{
549							File: h.file, Line: h.line, Kind: "deleted",
550							Current: h.current, Expected: d.raw,
551							Identifier: d.id, Confidence: 0.65, Evidence: d.ev,
552							Reason:    fmt.Sprintf("history asserts `%s` near a peer state update, but that call is absent at this current locus", d.raw),
553							rankBoost: 3,
554						})
555					}
556					continue
557				}
558			}
559			if !isCallDeletion && len(d.hints) > 0 {
560				homes := regressionMissingAssignmentHomes(files, d)
561				if len(homes) > 0 {
562					for _, h := range homes {
563						anomalies = append(anomalies, regressionAnomaly{
564							File: h.file, Line: h.line, Kind: "deleted",
565							Current: h.current, Expected: d.raw,
566							Identifier: d.id, Confidence: 0.65, Evidence: d.ev,
567							Reason:    fmt.Sprintf("history asserts `%s` in this hinted file, but that assignment is absent at this current locus", d.raw),
568							rankBoost: 1,
569						})
570					}
571					continue
572				}
573			}
574			if anyHas(d.target+d.rhs) || (!isCallDeletion && !anyHas(d.id)) {
575				continue
576			}
577			// Locate the home file: prefer one that also holds the RHS token (the natural site of
578			// the assignment), else the first file where the identifier appears.
579			home, line, cur := regressionHomeFile(files, d.id, d.rhs, d.hints)
580			if home == "" {
581				continue
582			}
583			invariantKind := "assignment"
584			if isCallDeletion {
585				invariantKind = "call"
586			}
587			rankBoost := 0
588			if len(d.hints) > 0 {
589				rankBoost = 1
590			}
591			if isCallDeletion {
592				rankBoost = 2
593				if len(d.hints) > 0 {
594					rankBoost = 3
595				}
596			}
597			anomalies = append(anomalies, regressionAnomaly{
598				File: home, Line: line, Kind: "deleted",
599				Current: cur, Expected: d.raw,
600				Identifier: d.id, Confidence: 0.65, Evidence: d.ev,
601				Reason:    fmt.Sprintf("history asserts `%s` but that %s is absent everywhere in the current tree", d.raw, invariantKind),
602				rankBoost: rankBoost,
603			})
604		}
605	
606		anomalies = annotateRegressionLocationContext(regressionDedupeRank(anomalies), files)
607		if limit > 0 && len(anomalies) > limit {
608			anomalies = anomalies[:limit]
609		}
610		if len(anomalies) > regressionMaxAnomalies {
611			anomalies = anomalies[:regressionMaxAnomalies]
612		}
613		if anomalies == nil {
614			anomalies = []regressionAnomaly{}
615		}
616		return anomalies, len(files), warnings
617	}
