625	func regressionMissingCallHomes(files []candFile, d deleteSignal) []regressionHome {
626		if !strings.HasSuffix(d.target, "(") || len(d.anchors) == 0 {
627			return nil
628		}
629		callNeedle := d.target + d.rhs
630		hinted := map[string]struct{}{}
631		for _, h := range d.hints {
632			hinted[filepath.Clean(h)] = struct{}{}
633		}
634		scan := func(requireHint bool) []regressionHome {
635			var homes []regressionHome
636			seen := map[string]struct{}{}
637			for _, f := range files {
638				if requireHint {
639					if _, ok := hinted[f.clean]; !ok {
640						continue
641					}
642				}
643				for i, n := range f.norm {
644					if regressionIsComment(f.lines[i]) {
645						continue
646					}
647					anchorHit := false
648					for _, anchor := range d.anchors {
649						if strings.Contains(n, anchor+d.rhs) {
650							anchorHit = true
651							break
652						}
653					}
654					if !anchorHit || regressionForwardWindowHas(f, i, callNeedle, 6) {
655						continue
656					}
657					key := f.clean + ":" + strconv.Itoa(i+1)
658					if _, ok := seen[key]; ok {
659						continue
660					}
661					seen[key] = struct{}{}
662					homes = append(homes, regressionHome{file: f.clean, line: i + 1, current: strings.TrimSpace(f.lines[i])})
663				}
664			}
665			return homes
666		}
667		if len(hinted) > 0 {
668			if homes := scan(true); len(homes) > 0 {
669				return homes
670			}
671		}
672		return scan(false)
673	}
