675	func regressionMissingAssignmentHomes(files []candFile, d deleteSignal) []regressionHome {
676		if strings.HasSuffix(d.target, "(") || len(d.hints) == 0 {
677			return nil
678		}
679		assignmentNeedle := d.target + d.rhs
680		hinted := map[string]struct{}{}
681		for _, h := range d.hints {
682			hinted[filepath.Clean(h)] = struct{}{}
683		}
684		var homes []regressionHome
685		seen := map[string]struct{}{}
686		for _, f := range files {
687			if _, ok := hinted[f.clean]; !ok {
688				continue
689			}
690			for _, h := range regressionAssignmentCandidateHomes(f, d) {
691				if regressionAssignmentHomeHas(f, h.line, assignmentNeedle) {
692					continue
693				}
694				key := h.file + ":" + strconv.Itoa(h.line)
695				if _, ok := seen[key]; ok {
696					continue
697				}
698				seen[key] = struct{}{}
699				homes = append(homes, h)
700				if len(homes) >= 8 {
701					return homes
702				}
703			}
704		}
705		return homes
706	}
