708	func regressionAssignmentCandidateHomes(f candFile, d deleteSignal) []regressionHome {
709		var homes []regressionHome
710		seenLine := map[int]struct{}{}
711		var preferredLines []int
712		var rhsLines []int
713		fileHasRHS := false
714		if d.rhs != "" {
715			for i, n := range f.norm {
716				if regressionIsComment(f.lines[i]) {
717					continue
718				}
719				if strings.Contains(n, d.rhs) {
720					fileHasRHS = true
721					break
722				}
723			}
724		}
725		collect := func(needle string) {
726			if needle == "" {
727				return
728			}
729			for i, n := range f.norm {
730				if !strings.Contains(n, needle) || regressionIsComment(f.lines[i]) {
731					continue
732				}
733				if len(regressionFunctionPattern.FindStringSubmatch(strings.TrimSpace(f.lines[i]))) == 2 {
734					continue
735				}
736				line := i + 1
737				if needle == d.id {
738					if fileHasRHS && !regressionSymbolHas(f, line, d.rhs) {
739						continue
740					}
741					if regressionNearbyCandidateSeenInSameSymbol(f.lines, preferredLines, line, 2) {
742						continue
743					}
744				}
745				if needle == d.rhs {
746					if regressionNearbyCandidateSeenInSameSymbol(f.lines, preferredLines, line, 2) ||
747						regressionNearbyCandidateSeenInSameSymbol(f.lines, rhsLines, line, 2) {
748						continue
749					}
750				}
751				if _, ok := seenLine[line]; ok {
752					continue
753				}
754				seenLine[line] = struct{}{}
755				if needle == d.id {
756					preferredLines = append(preferredLines, line)
757				}
758				if needle == d.rhs {
759					rhsLines = append(rhsLines, line)
760				}
761				homes = append(homes, regressionHome{file: f.clean, line: line, current: strings.TrimSpace(f.lines[i])})
762			}
763		}
764		collect(d.id)
765		collect(d.rhs)
766		return homes
767	}
