769	func regressionAssignmentHomeHas(f candFile, line int, needle string) bool {
770		if _, _, ok := regressionEnclosingSymbolRange(f.lines, line); ok {
771			return regressionWindowHas(f, line-1, needle, 2)
772		}
773		return regressionWindowHas(f, line-1, needle, 8)
774	}
