776	func regressionNearbyCandidateSeenInSameSymbol(src []string, lines []int, line, radius int) bool {
777		start, end, ok := regressionEnclosingSymbolRange(src, line)
778		for _, seen := range lines {
779			if seen < line-radius || seen > line+radius {
780				continue
781			}
782			seenStart, seenEnd, seenOK := regressionEnclosingSymbolRange(src, seen)
783			if ok && seenOK && (start != seenStart || end != seenEnd) {
784				continue
785			}
786			if ok != seenOK {
787				continue
788			}
789			if ok || !seenOK {
790				return true
791			}
792		}
793		return false
794	}
