815		if end > len(f.norm) {
816			end = len(f.norm)
817		}
818		for i := start; i < end; i++ {
819			if regressionIsComment(f.lines[i]) {
820				continue
821			}
822			if strings.Contains(f.norm[i], needle) {
823				return true
