845	// regressionHomeFile returns the best (file, line, text) to attribute a deletion to: a file
846	// containing both the identifier and the RHS token, else the first file holding the identifier.
847	func regressionHomeFile(files []candFile, id, rhs string, hints []string) (string, int, string) {
848		findIDLine := func(f candFile, allowComment bool) (int, string, bool) {
849			for i, n := range f.norm {
850				if !strings.Contains(n, id) {
851					continue
852				}
853				if !allowComment && regressionIsComment(f.lines[i]) {
854					continue
855				}
856				return i + 1, strings.TrimSpace(f.lines[i]), true
857			}
858			return 0, "", false
859		}
860		findRHSLine := func(f candFile, allowComment bool) (int, string, bool) {
861			if rhs == "" {
862				return 0, "", false
863			}
864			for i, n := range f.norm {
865				if !strings.Contains(n, rhs) || !strings.Contains(n, "=") {
866					continue
867				}
868				if !allowComment && regressionIsComment(f.lines[i]) {
869					continue
870				}
871				return i + 1, strings.TrimSpace(f.lines[i]), true
872			}
873			for i, n := range f.norm {
874				if !strings.Contains(n, rhs) {
875					continue
876				}
877				if !allowComment && regressionIsComment(f.lines[i]) {
878					continue
879				}
880				return i + 1, strings.TrimSpace(f.lines[i]), true
881			}
882			return 0, "", false
883		}
884		if len(hints) > 0 {
885			hinted := map[string]struct{}{}
886			for _, h := range hints {
887				hinted[filepath.Clean(h)] = struct{}{}
888			}
889			for _, f := range files {
890				if _, ok := hinted[f.clean]; !ok {
891					continue
892				}
893				if line, cur, ok := findIDLine(f, false); ok {
894					return f.clean, line, cur
895				}
896				if line, cur, ok := findRHSLine(f, false); ok {
897					return f.clean, line, cur
898				}
899			}
900			for _, f := range files {
901				if _, ok := hinted[f.clean]; !ok {
902					continue
903				}
904				if line, cur, ok := findIDLine(f, true); ok {
905					return f.clean, line, cur
906				}
907				if line, cur, ok := findRHSLine(f, true); ok {
908					return f.clean, line, cur
909				}
910			}
911		}
912		if rhs != "" {
913			for _, f := range files {
914				if !fileHasNorm(f.norm, rhs) {
915					continue
916				}
917				if line, cur, ok := findIDLine(f, false); ok {
918					return f.clean, line, cur
919				}
920			}
921			for _, f := range files {
922				if !fileHasNorm(f.norm, rhs) {
923					continue
924				}
925				if line, cur, ok := findIDLine(f, true); ok {
926					return f.clean, line, cur
927				}
928			}
929		}
930		for _, f := range files {
931			if line, cur, ok := findIDLine(f, false); ok {
932				return f.clean, line, cur
933			}
934		}
935		for _, f := range files {
936			if line, cur, ok := findIDLine(f, true); ok {
937				return f.clean, line, cur
938			}
939		}
940		return "", 0, "(absent)"
941	}
