952	func dedupeChanges(in []changeSignal) []changeSignal {
953		seen := map[string]struct{}{}
954		var out []changeSignal
955		for _, c := range in {
956			k := c.id + "|" + c.operand
957			if _, ok := seen[k]; ok {
958				continue
959			}
960			seen[k] = struct{}{}
961			out = append(out, c)
962		}
963		return out
964	}
