966	func dedupeDeletes(in []deleteSignal) []deleteSignal {
967		seen := map[string]int{}
968		var out []deleteSignal
969		for _, d := range in {
970			k := d.target + "|" + d.rhs
971			if idx, ok := seen[k]; ok {
972				out[idx].hints = mergeRegressionHints(out[idx].hints, d.hints)
973				out[idx].anchors = mergeRegressionHints(out[idx].anchors, d.anchors)
974				continue
975			}
976			seen[k] = len(out)
977			out = append(out, d)
978		}
979		return out
980	}
