982	func regressionDedupeRank(in []regressionAnomaly) []regressionAnomaly {
983		seen := map[string]struct{}{}
984		var out []regressionAnomaly
985		for _, a := range in {
986			key := a.File + "|" + strconv.Itoa(a.Line) + "|" + a.Kind + "|" + regressionDespace(a.Expected)
987			if _, ok := seen[key]; ok {
988				continue
989			}
990			seen[key] = struct{}{}
991			out = append(out, a)
992		}
993		sort.SliceStable(out, func(i, j int) bool {
994			if out[i].rankBoost != out[j].rankBoost {
995				return out[i].rankBoost > out[j].rankBoost
996			}
997			if out[i].Confidence != out[j].Confidence {
998				return out[i].Confidence > out[j].Confidence
999			}
1000			return out[i].File < out[j].File
1001		})
1002		return out
1003	}
