1005	var regressionFunctionPattern = regexp.MustCompile(`^func\s+(?:\([^)]+\)\s*)?([A-Za-z_][A-Za-z0-9_]*)\s*\(`)
1006	
1007	func regressionEnclosingSymbol(lines []string, line int) string {
1008		start, _, ok := regressionEnclosingSymbolRange(lines, line)
1009		if !ok {
1010			return ""
1011		}
1012		match := regressionFunctionPattern.FindStringSubmatch(strings.TrimSpace(lines[start]))
1013		if len(match) == 2 {
1014			return match[1]
1015		}
1016		return ""
1017	}
1018	
1019	func regressionEnclosingSymbolRange(lines []string, line int) (int, int, bool) {
1020		if line <= 0 || line > len(lines) {
1021			return 0, 0, false
1022		}
1023		start := line - 1
1024		for i := start; i >= 0 && i >= start-250; i-- {
1025			match := regressionFunctionPattern.FindStringSubmatch(strings.TrimSpace(lines[i]))
1026			if len(match) == 2 {
1027				end := len(lines)
1028				for j := i + 1; j < len(lines); j++ {
1029					if len(regressionFunctionPattern.FindStringSubmatch(strings.TrimSpace(lines[j]))) == 2 {
1030						end = j
1031						break
1032					}
1033				}
1034				return i, end, true
1035			}
1036		}
1037		return 0, 0, false
1038	}
