1040	func annotateRegressionLocationContext(anomalies []regressionAnomaly, files []candFile) []regressionAnomaly {
1041		if len(anomalies) == 0 {
1042			return anomalies
1043		}
1044		byFile := map[string]candFile{}
1045		for _, f := range files {
1046			byFile[f.clean] = f
1047		}
1048		for i := range anomalies {
1049			if anomalies[i].Symbol != "" {
1050				continue
1051			}
1052			if f, ok := byFile[filepath.Clean(anomalies[i].File)]; ok {
1053				anomalies[i].Symbol = regressionEnclosingSymbol(f.lines, anomalies[i].Line)
1054			}
1055		}
1056		for i := range anomalies {
1057			var related []string
1058			for j := range anomalies {
1059				if i == j || anomalies[i].File != anomalies[j].File || anomalies[i].Kind != anomalies[j].Kind || anomalies[j].Line <= 0 {
1060					continue
1061				}
1062				if !regressionRelatedLocationMatch(anomalies[i], anomalies[j]) {
1063					continue
1064				}
1065				loc := fmt.Sprintf("%s:%d", anomalies[j].File, anomalies[j].Line)
1066				if anomalies[j].Symbol != "" {
1067					loc += " (" + anomalies[j].Symbol + ")"
1068				}
1069				related = append(related, loc)
1070				if len(related) >= 6 {
1071					break
1072				}
1073			}
1074			anomalies[i].RelatedLocations = related
1075		}
1076		return anomalies
1077	}
