1079	func regressionRelatedLocationMatch(a, b regressionAnomaly) bool {
1080		aExpected := regressionDespace(a.Expected)
1081		bExpected := regressionDespace(b.Expected)
1082		if aExpected != "" || bExpected != "" {
1083			return aExpected != "" && aExpected == bExpected
1084		}
1085		return a.Identifier != "" && b.Identifier != "" && strings.EqualFold(a.Identifier, b.Identifier)
1086	}
