1088	func runRegressionDetect(ctx context.Context, cmd *cobra.Command, opts Options, ro regressionDetectorOptions, query string) error {
1089		if ro.limit <= 0 {
1090			ro.limit = 20
1091		}
1092		target := agentSurfaceTarget(opts, nil)
1093		status, err := buildBrainStatusReport(ctx, opts, target)
1094		if err != nil {
1095			return err
1096		}
1097		var semSource *semanticSourceManifest
1098		if status.Manifest != nil && status.Manifest.Sources != nil {
1099			semSource = status.Manifest.Sources.Semantic
1100		}
1101		anomalies, scanned, warnings := detectRegressionAnomalies(status.Brain.Path, status.Repo.Root, semSource, query, ro.limit, ro.includeDeletions)
1102		if ro.locationOnly {
1103			// Hand only the suspected location, not the fix — so a fair A/B measures detection, not
1104			// the agent pasting a harness-computed `expected`.
1105			for i := range anomalies {
1106				anomalies[i].Expected = ""
1107				anomalies[i].Current = ""
1108				anomalies[i].Reason = "suspected regression site (location only)"
1109				if anomalies[i].Symbol != "" || len(anomalies[i].RelatedLocations) > 0 {
1110					anomalies[i].Reason = "suspected regression site (location only); inspect the enclosing symbol and related same-file locations"
1111				}
1112			}
1113		}
1114		report := regressionReport{
1115			SchemaVersion: reviewReportSchemaVersion,
1116			GeneratedAt:   opts.Now().UTC(),
1117			Query:         query,
1118			RepoPath:      status.Repo.Root,
1119			BrainPath:     status.Brain.Path,
1120			Anomalies:     anomalies,
1121			Scanned:       scanned,
1122			Warnings:      warnings,
1123		}
1124		if ro.json {
1125			return writeJSON(cmd, report)
1126		}
1127		out := cmd.OutOrStdout()
1128		if len(anomalies) == 0 {
1129			fmt.Fprintf(out, "No suspected regressions for %q (scanned %d files).\n", query, scanned)
1130			for _, w := range warnings {
1131				fmt.Fprintf(out, "  note: %s\n", w)
1132			}
1133			return nil
1134		}
1135		fmt.Fprintf(out, "Suspected regressions for %q:\n", query)
1136		for _, a := range anomalies {
1137			fmt.Fprintf(out, "  [%s, conf %.2f] %s:%d\n    expected: %s\n    current:  %s\n    why: %s\n    evidence: %s\n",
1138				a.Kind, a.Confidence, a.File, a.Line, a.Expected, a.Current, a.Reason, a.Evidence)
1139		}
1140		return nil
1141	}
1142	
1143	func newInspectRegressionsCommand(opts Options) *cobra.Command {
1144		ro := regressionDetectorOptions{limit: 20}
1145		cmd := &cobra.Command{
1146			Use:   "regressions <query>",
1147			Short: "Flag suspected regressions by comparing current code to session history",
1148			Args:  cobra.ExactArgs(1),
1149			RunE: func(cmd *cobra.Command, args []string) error {
1150				return runRegressionDetect(cmd.Context(), cmd, opts, ro, args[0])
1151			},
1152		}
1153		cmd.Flags().IntVar(&ro.limit, "limit", 20, "Maximum suspected regressions to return")
1154		cmd.Flags().BoolVar(&ro.json, "json", false, "Emit machine-readable JSON")
1155		cmd.Flags().BoolVar(&ro.includeDeletions, "include-deletions", false, "Also flag deleted assignments (higher recall, noisier)")
1156		cmd.Flags().BoolVar(&ro.locationOnly, "location-only", false, "Emit only the suspected file:line, not the expected/current values")
1157		return cmd
1158	}
1159	
1160	// ---- Diff-less review: the versioned contract `entire review` / `labs investigate` are INTENDED to
1161	//      consume (cross-repo, NOT yet wired) ----
1162	//
1163	// This is the machine contract, not a human verb (the human review surface is `entire review` in the
1164	// cli; this command is hidden — see root.go). When wired, the cli's `entire review` WOULD gain a
1165	// diff-less mode that shells `entire-brain review <query> --json`, checks reviewReport.schema_version,
1166	// and folds these findings into the review prompt — reviewing the working tree against the brain's
1167	// memory instead of a branch-vs-base diff (the graceful upgrade entire-brain gets from entire-sem).
1168	// That cli mode is prototyped on a held branch, NOT landed. Full contract + consumer design:
1169	// docs/diffless_review_seam.md.
1170	//
1171	// Consumer status (cross-repo, in entireio/cli — NOT in this repo, do not claim either is shipped):
1172	//   - `entire review`            : prototyped on a held branch off Peyton's review redesign; NOT landed.
1173	//   - `entire labs investigate`  : DESIGNED, NOT WIRED.
1174	//
1175	// TODO(diffless-seam): wire `entire labs investigate` to consume this contract — fold the suspected
1176	// regressions for the investigation topic into the per-turn shared context so every brainstorming
1177	// agent sees them. No diff concept there, so it fires whenever the brain is installed. Design lives in
1178	// docs/diffless_review_seam.md; the cli-side hook is prototyped on the held branch, not landed here.
1179	
1180	// reviewReportSchemaVersion is the contract version `entire review` is intended to bind to (the
1181	// consumer is not yet landed; see above). Bump on any breaking change to reviewReport / reviewFinding
1182	// (field rename/removal/semantics).
1183	const reviewReportSchemaVersion = 1
1184	
1185	type reviewFinding struct {
1186		Severity   string  `json:"severity"` // high (reserved) | medium (changed) | low (deleted)
1187		File       string  `json:"file"`
1188		Line       int     `json:"line,omitempty"`
1189		Title      string  `json:"title"`
1190		Detail     string  `json:"detail"`
1191		Evidence   string  `json:"evidence"`
1192		Confidence float64 `json:"confidence"`
1193	}
1194	
1195	type reviewReport struct {
1196		SchemaVersion int             `json:"schema_version"`
1197		GeneratedAt   time.Time       `json:"generated_at"`
1198		Mode          string          `json:"mode"`
1199		Query         string          `json:"query"`
1200		RepoPath      string          `json:"repo_path"`
1201		BrainPath     string          `json:"brain_path"`
1202		Summary       string          `json:"summary"`
1203		Findings      []reviewFinding `json:"findings"`
1204		Warnings      []string        `json:"warnings,omitempty"`
1205	}
1206	
1207	// regressionSeverity maps detector confidence to a review severity. Every finding the current
1208	// heuristic detector emits is *suspected* — `changed` (0.8) is precise but rename-ambiguous and
1209	// `deleted` (0.65) is noisier/opt-in — so none warrant "high". That tier is reserved for a future
1210	// high-confidence signal (a durable fact bound to a locus with recency), so the machine severity
1211	// never contradicts the "could be a rename — verify" hedge: changed -> medium, deleted -> low.
1212	func regressionSeverity(conf float64) string {
1213		switch {
1214		case conf >= 0.9:
1215			return "high" // reserved: no heuristic finding reaches this today
1216		case conf >= 0.7:
1217			return "medium"
1218		default:
1219			return "low"
1220		}
1221	}
1222	
1223	func anomalyToReviewFinding(a regressionAnomaly) reviewFinding {
1224		detail := "suspected regression at this location — verify against the brain's history."
1225		if a.Expected != "" {
1226			detail = fmt.Sprintf("history shows `%s`; current is `%s` — verify this change is intentional (could also be a rename).", a.Expected, a.Current)
1227		}
1228		return reviewFinding{
1229			Severity:   regressionSeverity(a.Confidence),
1230			File:       a.File,
1231			Line:       a.Line,
1232			Title:      fmt.Sprintf("Suspected regression: `%s` %s", a.Identifier, a.Kind),
1233			Detail:     detail,
1234			Evidence:   a.Evidence,
1235			Confidence: a.Confidence,
1236		}
1237	}
1238	
1239	func runBrainReview(ctx context.Context, cmd *cobra.Command, opts Options, ro regressionDetectorOptions, query string) error {
1240		if ro.limit <= 0 {
1241			ro.limit = 20
1242		}
1243		target := agentSurfaceTarget(opts, nil)
1244		status, err := buildBrainStatusReport(ctx, opts, target)
1245		if err != nil {
1246			return err
1247		}
1248		var semSource *semanticSourceManifest
1249		if status.Manifest != nil && status.Manifest.Sources != nil {
1250			semSource = status.Manifest.Sources.Semantic
1251		}
1252		anomalies, _, warnings := detectRegressionAnomalies(status.Brain.Path, status.Repo.Root, semSource, query, ro.limit, ro.includeDeletions)
1253		if ro.locationOnly {
1254			// Parity with `inspect regressions --location-only`: hand the suspected site, not the fix,
1255			// so a fair consumer/A-B measures detection rather than pasting a harness-computed value.
1256			for i := range anomalies {
1257				anomalies[i].Expected = ""
1258				anomalies[i].Current = ""
1259				anomalies[i].Reason = "suspected regression site (location only)"
1260			}
1261		}
1262		findings := make([]reviewFinding, 0, len(anomalies))
1263		for _, a := range anomalies {
1264			findings = append(findings, anomalyToReviewFinding(a))
1265		}
1266		summary := "Diff-less review: no suspected regressions (current tree matches the brain's memory)."
1267		if len(findings) > 0 {
1268			summary = fmt.Sprintf("Diff-less review: %d suspected regression(s) — verify each before acting.", len(findings))
1269		}
1270		report := reviewReport{
1271			SchemaVersion: reviewReportSchemaVersion,
1272			GeneratedAt:   opts.Now().UTC(),
1273			Mode:          "diff-less (brain memory vs current tree)",
1274			Query:         query,
1275			RepoPath:      status.Repo.Root,
1276			BrainPath:     status.Brain.Path,
1277			Summary:       summary,
1278			Findings:      findings,
1279			Warnings:      warnings,
1280		}
1281		if ro.json {
1282			return writeJSON(cmd, report)
1283		}
1284		out := cmd.OutOrStdout()
1285		fmt.Fprintln(out, report.Summary)
1286		for _, f := range findings {
1287			fmt.Fprintf(out, "\n  [%s] %s\n    %s:%d\n    %s\n    evidence: %s\n",
1288				strings.ToUpper(f.Severity), f.Title, f.File, f.Line, f.Detail, f.Evidence)
1289		}
1290		for _, w := range warnings {
1291			fmt.Fprintf(out, "  note: %s\n", w)
1292		}
1293		return nil
1294	}
1295	
1296	func newBrainReviewCommand(opts Options) *cobra.Command {
1297		ro := regressionDetectorOptions{limit: 20}
1298		cmd := &cobra.Command{
1299			Use:   "review <query>",
1300			Short: "Diff-less review: flag suspected regressions in the current tree vs the brain's memory",
1301			Args:  cobra.ExactArgs(1),
1302			RunE: func(cmd *cobra.Command, args []string) error {
1303				return runBrainReview(cmd.Context(), cmd, opts, ro, args[0])
1304			},
1305		}
1306		cmd.Flags().IntVar(&ro.limit, "limit", 20, "Maximum findings")
1307		cmd.Flags().BoolVar(&ro.json, "json", false, "Emit machine-readable JSON")
1308		cmd.Flags().BoolVar(&ro.includeDeletions, "include-deletions", false, "Also flag deleted assignments (lower confidence, noisier)")
1309		cmd.Flags().BoolVar(&ro.locationOnly, "location-only", false, "Emit only the suspected file:line, not the expected/current values")
1310		return cmd
1311	}
